/* From Uiverse.io by Subaashbala  - Tags: loader, animated, loading animation */
.__UIV_SCOPE__ .loaderContainer {
  display: flex;
  width: 9em;
  overflow: hidden;
  gap: 0.5em;
}
.__UIV_SCOPE__ .particleContainer {
  display: flex;
  gap: 0.5em;
  animation: slide 2000ms linear infinite;
}
.__UIV_SCOPE__ .particleContainer div {
  width: 2.5em;
  aspect-ratio: 1;
  border-radius: 5px;
  background: whitesmoke;
  transform-origin: left bottom;
  animation: squeeze 750ms ease-in-out infinite;
}
.__UIV_SCOPE__ .particleContainer div:nth-child(2) {
  animation-delay: 50ms;
}
.__UIV_SCOPE__ .particleContainer div:last-child {
  animation-delay: 100ms;
}
@keyframes squeeze {
  0% {
    transform: scale(1) translateY(0);
  }
  50% {
    transform: scale(0.75);
  }
  75% {
    transform: scale(1.05);
  }
  100% {
    transform: sclae(1);
  }
}
@keyframes slide {
  from {
    transform: translateX(0%);
  }
  to {
    transform: translateX(calc(-50% + 1.25em));
  }
}
